  ///
  /// Fails if the wallet has been locked.
  Future<String?> lwsConsentNeeded() => RustLib.instance.api
      .crateApiWalletsOpenWalletLwsConsentNeeded(that: this);

  /// Hands out the next subaddress in account 0 and saves the wallet.
  ///
  /// # Errors
  ///
  /// Fails if the wallet has been locked or cannot be saved.
  Future<AddressRow> newAddress({required String label}) => RustLib.instance.api
      .crateApiWalletsOpenWalletNewAddress(that: this, label: label);

  /// Builds and signs a transaction paying `payments`, or, with
  /// `sweep_to`, sending everything spendable to that address. Nothing is
  /// published; show [`PreparedSend::summary`] and call
  /// [`OpenWallet::confirm_send`].
  ///
  /// # Errors
  ///
  /// See [`SendError`]; sync must have reached the chain tip first.
  Future<PreparedSend> prepareSend({
    required List<Payment> payments,
    String? sweepTo,
    required FeePriority priority,
  }) => RustLib.instance.api.crateApiWalletsOpenWalletPrepareSend(
    that: this,
    payments: payments,
    sweepTo: sweepTo,
    priority: priority,
  );

  /// Returns the seed words after re-checking the password. `None` for
  /// wallets restored from keys or view-only wallets, which have no seed.
  ///
  /// # Errors
  ///
  /// [`WalletError::WrongPassword`] if the password does not open the file.
  Future<List<String>?> revealSeed({required String password}) => RustLib
      .instance
      .api
      .crateApiWalletsOpenWalletRevealSeed(that: this, password: password);

  /// The transaction key of a transaction this wallet sent, after
  /// checking the password. With it and the recipient's address, anyone
  /// can verify the payment (for example with `check_tx_key`).
  ///
  /// # Errors
  ///
  /// [`WalletError::WrongPassword`], or [`WalletError::NotFound`] if no key
  /// is stored for `tx_hash`.
  Future<String> revealTxKey({
    required String txHash,
    required String password,
  }) => RustLib.instance.api.crateApiWalletsOpenWalletRevealTxKey(
    that: this,
    txHash: txHash,
    password: password,
  );

  /// Saves a recipient, replacing any entry with the same address.
  ///
  /// # Errors
  ///
  /// [`WalletError::EmptyName`], or [`WalletError::BadAddress`] for an
  /// address not on this wallet's network.
  Future<void> saveContact({required String name, required String address}) =>
      RustLib.instance.api.crateApiWalletsOpenWalletSaveContact(
        that: this,
        name: name,
        address: address,
      );

  /// Sets or clears (empty string) an address label and saves the wallet.
  ///
  /// # Errors
  ///
  /// Fails if the wallet has been locked or cannot be saved.
  Future<void> setAddressLabel({
    required int account,
    required int index,
    required String label,
  }) => RustLib.instance.api.crateApiWalletsOpenWalletSetAddressLabel(
    that: this,
    account: account,
    index: index,
    label: label,
  );

  /// Switches between full sync and a light wallet server. Stops sync and
  /// clears what was scanned; start sync again afterwards.
  ///
  /// # Errors
  ///
  /// Fails if the wallet has been locked or cannot be saved.
  Future<void> setSyncMode({required SyncMode mode}) => RustLib.instance.api
      .crateApiWalletsOpenWalletSetSyncMode(that: this, mode: mode);

  /// Sets the note for `tx_hash`; an empty note removes it.
  ///
  /// # Errors
  ///
  /// Fails if the wallet has been locked or cannot be saved.
  Future<void> setTxNote({required String txHash, required String note}) =>
      RustLib.instance.api.crateApiWalletsOpenWalletSetTxNote(
        that: this,
        txHash: txHash,
        note: note,
      );

  /// Starts syncing in the background and reports through `sink`. Keeps
  /// following new blocks until [`OpenWallet::stop_sync`] or
  /// [`OpenWallet::lock`]. Calling it again restarts sync.
  Stream<SyncEvent> startSync() =>
      RustLib.instance.api.crateApiWalletsOpenWalletStartSync(that: this);

  /// Stops background sync after the current step.
  void stopSync() =>
      RustLib.instance.api.crateApiWalletsOpenWalletStopSync(that: this);

  /// The wallet's registry entry.
  ///
  /// # Errors
  ///
  /// Fails if the wallet has been locked.
  WalletSummary summary() =>
      RustLib.instance.api.crateApiWalletsOpenWalletSummary(that: this);

  /// Notes and sending details for `tx_hash` (hex).
  ///
  /// # Errors
  ///
  /// Fails if the wallet has been locked.
  TxDetails txDetails({required String txHash}) => RustLib.instance.api
      .crateApiWalletsOpenWalletTxDetails(that: this, txHash: txHash);
}

